fn sort(q: *[5]f64, n: usize) void { for (1..n) |i| { const x=q[i]; var j=i; while(j>0 and q[j-1]>x):(j-=1){q[j]=q[j-1];} q[j]=x; } }
export fn p2_quantile_estimator(v:[*]const i64,n:usize) f64 {if(n<2 or n>65 or v[0]<1 or v[0]>64 or n!=@as(usize,@intCast(v[0]))+1)return -1e300;const count:usize=@intCast(v[0]);var q=[_]f64{0}**5;var pos=[_]f64{0}**5;var desired=[_]f64{0}**5;const inc=[_]f64{0,.25,.5,.75,1};var seen:usize=0;for(0..count)|z|{if(v[z+1]<-2147483648 or v[z+1]>2147483647)return -1e300;const x=@as(f64,@floatFromInt(v[z+1]));if(seen<5){q[seen]=x;seen+=1;if(seen==5){sort(&q,5);for(0..5)|i|{pos[i]=@floatFromInt(i+1);desired[i]=@floatFromInt(i+1);}}continue;}var k:usize=3;if(x<q[0]){q[0]=x;k=0;}else{for(1..4)|i|{if(x<q[i]){k=i-1;break;}}if(x>q[4])q[4]=x;}for(k+1..5)|i|pos[i]+=1;for(0..5)|i|desired[i]+=inc[i];for(1..4)|i|{const drift=desired[i]-pos[i];const sr=drift>=1 and pos[i+1]-pos[i]>1;const sl=drift<=-1 and pos[i-1]-pos[i]<-1;if(!sr and !sl)continue;const dir:f64=if(sr)1 else -1;const l=pos[i]-pos[i-1];const r=pos[i+1]-pos[i];const cand=q[i]+dir/(l+r)*((l+dir)*(q[i+1]-q[i])/r+(r-dir)*(q[i]-q[i-1])/l);if(q[i-1]<cand and cand<q[i+1])q[i]=cand else{const nb:usize=@intCast(@as(isize,@intCast(i))+@as(isize,@intFromFloat(dir)));q[i]+=dir*(q[nb]-q[i])/(pos[nb]-pos[i]);}pos[i]+=dir;}}if(seen<5){sort(&q,count);const rank=0.5*@as(f64,@floatFromInt(count-1));const lo:usize=@intFromFloat(rank);const hi=@min(lo+1,count-1);return q[lo]+(rank-@as(f64,@floatFromInt(lo)))*(q[hi]-q[lo]);}return q[2];}
